572 src/app/globals.css
@import "tailwindcss";

/* ------------------------------------------------------------------
   DESIGN-TOKENS FÜR TAILWIND
   Gemessen standen auf der Startseite 9 verschiedene Schatten und
   3 verschiedene Animationskurven nebeneinander. Hier werden die
   Tailwind-Standards überschrieben, damit shadow-sm … shadow-2xl und
   alle transition-*-Klassen seitenweit dieselbe Handschrift tragen:
   weiche, mehrlagige Schatten statt eines harten Einzelschattens und
   eine Kurve, die zügig startet und ruhig ausläuft.
   ------------------------------------------------------------------ */
@theme {
  --default-transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  --default-transition-duration: 220ms;

  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.05), 0 1px 1px rgba(15, 23, 42, 0.03);
  --shadow: 0 1px 3px rgba(15, 23, 42, 0.06), 0 2px 6px -2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 2px 4px -1px rgba(15, 23, 42, 0.05), 0 6px 16px -4px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 4px 8px -2px rgba(15, 23, 42, 0.05), 0 14px 32px -8px rgba(15, 23, 42, 0.12);
  --shadow-xl: 0 8px 16px -4px rgba(15, 23, 42, 0.06), 0 24px 48px -12px rgba(15, 23, 42, 0.16);
  --shadow-2xl: 0 12px 24px -6px rgba(15, 23, 42, 0.08), 0 36px 72px -18px rgba(15, 23, 42, 0.22);

  /* ---------------- Ökovolt Design-System 2026 ---------------- */
  --font-sans: var(--font-inter), system-ui, "Segoe UI", Arial, sans-serif;
  --font-display: var(--font-manrope), var(--font-inter), system-ui, sans-serif;

  /* Markengrün als volle Skala (500 = #669933) */
  --color-ov-50: #f4f9ee;
  --color-ov-100: #e6f1d8;
  --color-ov-200: #cde3b1;
  --color-ov-300: #aed083;
  --color-ov-400: #8cba58;
  --color-ov-500: #669933;
  --color-ov-600: #558227;
  --color-ov-700: #436621;
  --color-ov-800: #37521e;
  --color-ov-900: #2f461c;

  /* Markenblau als Skala (700 = #003473) */
  --color-navy-50: #eef4fb;
  --color-navy-100: #d9e6f5;
  --color-navy-200: #b2cbe9;
  --color-navy-300: #7fa7d6;
  --color-navy-400: #4a7cbd;
  --color-navy-500: #1f5aa1;
  --color-navy-600: #0b4488;
  --color-navy-700: #003473;
  --color-navy-800: #03285a;
  --color-navy-900: #041d42;
  --color-navy-950: #03122b;

  /* Neutrale Töne mit leicht kühlem Stich – passend zum Navy */
  --color-ink-50: #f7f8fa;
  --color-ink-100: #eef0f4;
  --color-ink-200: #dfe3ea;
  --color-ink-300: #c4cad5;
  --color-ink-400: #97a0b0;
  --color-ink-500: #6b7486;
  --color-ink-600: #4e5667;
  --color-ink-700: #394050;
  --color-ink-800: #252b37;
  --color-ink-900: #151a24;

  /* Sonnen-Akzent: nur sparsam (Live-Daten, Highlights) */
  --color-sun-300: #ffd873;
  --color-sun-400: #ffc53d;
  --color-sun-500: #f5a70f;

  /* Warmer Papierton für ruhige Flächen */
  --color-sand-50: #fbfaf6;
  --color-sand-100: #f5f3ea;

  --radius-4xl: 2rem;
  --radius-5xl: 2.5rem;

  --animate-ov-float: ov-float 7s ease-in-out infinite;
  --animate-ov-marquee: ov-marquee 40s linear infinite;
  --animate-ov-pulse-dot: ov-pulse-dot 2s cubic-bezier(0.22, 1, 0.36, 1) infinite;
  --animate-ov-shimmer: ov-shimmer 2.4s linear infinite;
}

@keyframes ov-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes ov-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@keyframes ov-pulse-dot {
  0% { box-shadow: 0 0 0 0 rgba(140, 186, 88, 0.7); }
  70% { box-shadow: 0 0 0 10px rgba(140, 186, 88, 0); }
  100% { box-shadow: 0 0 0 0 rgba(140, 186, 88, 0); }
}
@keyframes ov-shimmer {
  from { background-position: -200% 0; }
  to { background-position: 200% 0; }
}

:root {
  --background: #ffffff;
  --foreground: #171717;

  /* Markenfarben als Variablen – bisher standen die Hex-Werte rund 500×
     verstreut als arbitrary values im Markup. Neue Komponenten nutzen diese
     Variablen; bestehende bleiben unangetastet. */
  --ov-gruen: #669933;
  --ov-gruen-hover: #558822;
  --ov-blau: #003473;
  --ov-gruen-tint: #f0f7e6;

  /* Lesbare Zeilenlänge. 72 Zeichen liegt im Optimum (45–75); ab etwa 85
     verliert das Auge beim Zeilenrücksprung die Spur. */
  --ov-measure: 72ch;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-inter), system-ui, "Segoe UI", Arial, sans-serif;
  /* Etwas mehr Durchschuss als der Browser-Standard – deutsche Texte haben
     lange Komposita, die dichter Satz schwer lesbar macht. */
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* Horizontales Überlaufen weiter unterbinden – aber mit `clip` statt
   `hidden`. `hidden` macht html/body zum Scroll-Container, und dann
   funktioniert position: sticky nicht mehr (der Header blieb nicht stehen).
   Ältere Browser ohne `clip` fallen auf `hidden` zurück. */
html, body {
  overflow-x: hidden;
  overflow-x: clip;
}

/* Sprungziele nicht unter dem (jetzt fixierten) Seitenkopf verstecken.
   Header: 104 px oben, 80 px beim Scrollen. */
html {
  scroll-padding-top: 7rem;
}

/* ------------------------------------------------------------------
   FEINHEITEN, AN DENEN MAN SORGFALT ERKENNT
   ------------------------------------------------------------------ */

/* Textmarkierung in Markenfarbe statt Browser-Blau. */
::selection {
  background: rgba(102, 153, 51, 0.24);
  color: inherit;
}

/* Tailwind 4 setzt Buttons auf den normalen Pfeil-Cursor. Gemessen zeigten
   21 von 37 Buttons keine Hand – Klickbares muss sich klickbar anfühlen. */
button:not(:disabled),
[role="button"],
[role="tab"],
summary,
label[for],
select {
  cursor: pointer;
}
button:disabled {
  cursor: not-allowed;
}

/* Überschriften gleichmäßig umbrechen, Fließtext ohne einzelnes Wort in
   der letzten Zeile. Progressive Verbesserung – ältere Browser umbrechen
   wie bisher.

   In @layer base, damit Tailwind-Utilities gewinnen: Unlayered hatte
   `text-wrap` (ein Teil der `white-space`-Kurzform) jedes `whitespace-nowrap`
   ausgehebelt und `hyphens: auto` jedes `[hyphens:manual]`. */
@layer base {
  h1, h2, h3, h4 {
    text-wrap: balance;
  }
  p, li, figcaption, blockquote, dd {
    text-wrap: pretty;
  }
  /* Ausnahme Akkordeon-Fragen: `balance` hält dort jede Zeile künstlich kurz,
     mobil stand die Frage in einer schmalen Spalte neben viel Leerraum. */
  h3:has(> button),
  summary {
    text-wrap: pretty;
  }

  /* Deutsche Komposita ("Einspeisevergütungssätze") sprengen sonst schmale
     Spalten. Silbentrennung nur im Fließtext, nie in Überschriften, und
     erst ab längeren Wörtern. */
  main p {
    -webkit-hyphens: auto;
    hyphens: auto;
    hyphenate-limit-chars: 10 4 4;
  }
}

/* Kerning und typografische Ligaturen der Schrift aktiv nutzen. */
body {
  font-kerning: normal;
  font-feature-settings: "kern", "liga", "calt";
}

/* Unterstreichungen mit Luft zur Grundlinie und in Schriftstärke. */
a {
  text-underline-offset: 0.2em;
  text-decoration-thickness: from-font;
}

/* Kein grauer Tap-Blitz auf Mobilgeräten. */
html {
  -webkit-tap-highlight-color: transparent;
}

/* Spürbares Drücken auf den Haupt-Handlungsaufrufen. `scale` statt
   `transform`, damit bestehende translate-Hover-Effekte erhalten bleiben. */
@media (prefers-reduced-motion: no-preference) {
  a[style*="669933"],
  button[style*="669933"] {
    transition-property: background-color, color, scale, box-shadow;
  }
  a[style*="669933"]:active,
  button[style*="669933"]:active {
    scale: 0.98;
  }
}

/* Dezente Scrollleiste im Markenton (dort, wo das System sie zeigt). */
html {
  scrollbar-color: #b9cda3 transparent;
}

/* Aufzählungszeichen in Markenfarbe, wo Listen welche zeigen. */
main li::marker {
  color: var(--ov-gruen);
}

/* ------------------------------------------------------------------
   SICHTBARER TASTATURFOKUS

   Vorher hatte KEIN einziges fokussierbares Element einen sichtbaren
   Fokusring (gemessen: 0 von 40). Wer per Tastatur navigiert, sah nicht,
   wo er steht – ein Verstoß gegen WCAG 2.4.7.

   :focus-visible greift nur bei Tastatur-/Programmfokus, nicht beim
   Mausklick. Der weiße Schatten unter dem grünen Ring sorgt dafür, dass
   der Fokus auch auf grünen und dunkelblauen Flächen sichtbar bleibt.
   ------------------------------------------------------------------ */
:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: 3px solid var(--ov-gruen);
  outline-offset: 2px;
  border-radius: 4px;
  box-shadow: 0 0 0 5px rgba(255, 255, 255, 0.9);
}

/* Auf dunklen Flächen den Ring aufhellen, damit er nicht im Grün verschwindet. */
:where(.bg-\[\#669933\], .bg-ov-600, .bg-\[\#003473\], .bg-\[\#0a1e35\])
  :where(a, button):focus-visible {
  outline-color: #ffffff;
  box-shadow: 0 0 0 5px rgba(0, 0, 0, 0.45);
}

/* ------------------------------------------------------------------
   LESBARE ZEILENLÄNGE
   Gemessen wurden bis zu 142 Zeichen pro Zeile – rund doppelt so viel
   wie lesbar ist. .ov-measure begrenzt den Fließtext, ohne das Layout
   der umgebenden Container anzufassen.
   ------------------------------------------------------------------ */
.ov-measure {
  max-width: var(--ov-measure);
}

/* ------------------------------------------------------------------
   BEWEGUNG REDUZIEREN
   114 Elemente animieren. Wer im Betriebssystem „Bewegung reduzieren"
   eingestellt hat, bekam das bisher trotzdem zu sehen.
   ------------------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

/* ------------------------------------------------------------------
   FORTSCHRITTSBALKEN DES HERO-SLIDERS
   Zeigt, wie lange der aktuelle Slide noch steht. Unter
   prefers-reduced-motion läuft kein Autoplay, also auch kein Balken –
   der Block oben setzt die Dauer dort ohnehin auf 0.
   ------------------------------------------------------------------ */
@keyframes ov-hero-fortschritt {
  from { width: 0%; }
  to { width: 100%; }
}
.ov-hero-fortschritt {
  animation-name: ov-hero-fortschritt;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

/* Weicher Tab-Wechsel. Startet bei 0.001 statt 0 Deckkraft und endet
   garantiert voll deckend – die alte Animation konnte bei opacity 0 hängen. */
@media (prefers-reduced-motion: no-preference) {
  .ov-tab-panel { animation: ov-tab-ein 220ms ease-out both; }
}
@keyframes ov-tab-ein {
  from { opacity: 0.001; transform: translateY(6px); }
  to   { opacity: 1; transform: none; }
}

/* Mobile CTA-Leiste sichtbar: Zurück-nach-oben-Button darüber anheben.
   Der Button setzt seine Position inline, deshalb !important. */
@media (max-width: 1023px) {
  body.ov-cta-sichtbar button[aria-label="Nach oben"] {
    bottom: 96px !important;
  }
  /* Rückruf-Icon (links unten) ebenfalls über die Leiste heben */
  body.ov-cta-sichtbar .ov-rueckruf-launcher {
    bottom: 96px;
  }
}

/* Mobilmenü offen: Hintergrund sperren, schwebende Elemente ausblenden. */
body.ov-menu-offen {
  overflow: hidden;
}
body.ov-menu-offen .ov-mobile-cta,
body.ov-menu-offen button[aria-label="Nach oben"] {
  display: none !important;
}

/* ==================================================================
   ÖKOVOLT DESIGN-SYSTEM 2026 – globale Bausteine
   Neue Komponenten (src/components/ui) nutzen diese Klassen.
   ================================================================== */

/* Überschriften grundsätzlich in der Display-Schrift. Bestehende Seiten
   profitieren sofort, ohne dass jede Komponente angefasst werden muss. */
h1, h2, h3, h4, .font-display {
  font-family: var(--font-display);
  letter-spacing: -0.015em;
}

/* Fluide Typografie – skaliert ohne Sprünge zwischen 360 und 1440 px. */
.ov-display {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.35rem, 1.45rem + 4vw, 4.75rem);
  line-height: 1.02;
  letter-spacing: -0.035em;
}
.ov-h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.1rem, 1.5rem + 2.7vw, 3.75rem);
  line-height: 1.06;
  letter-spacing: -0.03em;
}
.ov-h2 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.75rem, 1.3rem + 1.9vw, 3rem);
  line-height: 1.1;
  letter-spacing: -0.028em;
}
.ov-h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(1.2rem, 1.05rem + 0.6vw, 1.5rem);
  line-height: 1.25;
  letter-spacing: -0.015em;
}
.ov-lead {
  font-size: clamp(1.05rem, 0.98rem + 0.35vw, 1.25rem);
  line-height: 1.65;
}

.ov-container {
  width: 100%;
  max-width: 80rem;
  margin-inline: auto;
  padding-inline: 1.25rem;
}
@media (min-width: 768px) { .ov-container { padding-inline: 2rem; } }

/* Grüner Verlaufstext für Schlüsselwörter in Headlines */
.ov-text-gradient {
  background: linear-gradient(100deg, #8cba58 0%, #669933 45%, #3f7a2a 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.ov-text-gradient-light {
  background: linear-gradient(100deg, #d9f0b8 0%, #aed083 50%, #ffd873 110%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Feines Raster für dunkle Flächen */
.ov-grid-bg {
  background-image:
    linear-gradient(rgba(255,255,255,0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.045) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse at center, #000 30%, transparent 75%);
}
.ov-grid-bg-light {
  background-image:
    linear-gradient(rgba(0,52,115,0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,52,115,0.05) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse at top, #000 20%, transparent 70%);
}

/* Körnung gegen „Plastik-Look" auf großen Verläufen */
.ov-noise::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.06;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
}

/* Glas-Karte für Inhalte auf Bildern / dunklen Flächen */
.ov-glass {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(16px) saturate(140%);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
}

/* Karten mit Licht-Kante beim Hover */
.ov-card-hover {
  transition: transform 350ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 350ms cubic-bezier(0.22, 1, 0.36, 1), border-color 350ms;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ov-card-hover:hover {
    transform: translateY(-4px);
    box-shadow: 0 2px 6px -2px rgba(15, 23, 42, 0.06), 0 24px 48px -16px rgba(15, 23, 42, 0.18);
  }
}

/* Reveal-Animation (gesteuert von <Reveal/>). Ohne JS bleibt alles sichtbar. */
.ov-reveal {
  transition:
    opacity 800ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 800ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 800ms cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--ov-delay, 0ms);
}
.js-ready .ov-reveal:not(.is-visible) {
  opacity: 0;
  transform: translate3d(0, 28px, 0);
  filter: blur(6px);
}
.js-ready .ov-reveal[data-dir="left"]:not(.is-visible) { transform: translate3d(-32px, 0, 0); }
.js-ready .ov-reveal[data-dir="right"]:not(.is-visible) { transform: translate3d(32px, 0, 0); }
.js-ready .ov-reveal[data-dir="scale"]:not(.is-visible) { transform: scale(0.96); }
@media (prefers-reduced-motion: reduce) {
  .js-ready .ov-reveal:not(.is-visible) { opacity: 1; transform: none; filter: none; }
}

/* Schieberegler im Markenstil – für alle Rechner */
.ov-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 9999px;
  background: linear-gradient(to right, #669933 0%, #669933 var(--ov-fill, 50%), #dfe3ea var(--ov-fill, 50%), #dfe3ea 100%);
  outline: none;
}
.ov-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 26px;
  height: 26px;
  border-radius: 9999px;
  background: #fff;
  border: 2px solid #669933;
  box-shadow: 0 2px 10px rgba(21, 26, 36, 0.2);
  cursor: grab;
  transition: transform 150ms;
}
.ov-range::-webkit-slider-thumb:active { transform: scale(1.12); cursor: grabbing; }
.ov-range::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 9999px;
  background: #fff;
  border: 2px solid #669933;
  box-shadow: 0 2px 10px rgba(21, 26, 36, 0.2);
  cursor: grab;
}
.ov-range:focus-visible {
  box-shadow: 0 0 0 4px rgba(102, 153, 51, 0.3);
  /* sichtbarer Fokusring (WCAG 2.4.7) – überschreibt `outline: none` oben */
  outline: 3px solid var(--color-ov-600);
  outline-offset: 4px;
}

/* Zahlen in Kennzahlen immer gleich breit */
.ov-num { font-variant-numeric: tabular-nums; font-feature-settings: "tnum"; }

/* Scrollbare Leisten ohne sichtbare Scrollbar */
.ov-no-scrollbar { scrollbar-width: none; }
.ov-no-scrollbar::-webkit-scrollbar { display: none; }

/* Fließtext-Artikel (Ratgeber, Lexikon, Rechtstexte) */
.ov-prose { color: var(--color-ink-700); font-size: 1.0625rem; line-height: 1.75; }
.ov-prose > * + * { margin-top: 1.1em; }
.ov-prose h2 { font-size: clamp(1.5rem, 1.2rem + 1vw, 2rem); font-weight: 800; color: var(--color-ink-900); margin-top: 2em; line-height: 1.2; }
.ov-prose h3 { font-size: 1.25rem; font-weight: 700; color: var(--color-ink-900); margin-top: 1.6em; }
.ov-prose a { color: var(--color-ov-700); text-decoration: underline; text-decoration-color: var(--color-ov-300); }
.ov-prose a:hover { text-decoration-color: currentColor; }
.ov-prose ul { list-style: disc; padding-left: 1.25em; }
.ov-prose ol { list-style: decimal; padding-left: 1.25em; }
.ov-prose strong { color: var(--color-ink-900); }

/* Hero-Einstieg beim Laden (unabhängig vom Scroll-Observer) */
@keyframes ov-hero-in {
  from { opacity: 0.001; transform: translate3d(0, 22px, 0); filter: blur(4px); }
  to { opacity: 1; transform: none; filter: none; }
}
@media (prefers-reduced-motion: no-preference) {
  .ov-hero-in { animation: ov-hero-in 900ms cubic-bezier(0.22, 1, 0.36, 1) both; animation-delay: var(--ov-delay, 0ms); }
}

/* Schrittwechsel in Wizards (Konfigurator, Förder-Check) */
@keyframes ov-step-vor { from { opacity: 0.001; transform: translate3d(24px, 0, 0); } to { opacity: 1; transform: none; } }
@keyframes ov-step-zurueck { from { opacity: 0.001; transform: translate3d(-24px, 0, 0); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: no-preference) {
  .ov-step-vor { animation: ov-step-vor 450ms cubic-bezier(0.22, 1, 0.36, 1) both; }
  .ov-step-zurueck { animation: ov-step-zurueck 450ms cubic-bezier(0.22, 1, 0.36, 1) both; }
}

/* Rechtstexte: bestehendes Markup typografisch vereinheitlichen */
.ov-legal { color: var(--color-ink-700); font-size: 16px; line-height: 1.75; }
.ov-legal > div { max-width: none !important; padding: 0 !important; margin: 0 !important; }
.ov-legal h2 { font-family: var(--font-display); font-size: clamp(1.35rem, 1.15rem + 0.8vw, 1.75rem) !important; font-weight: 800; color: var(--color-ink-900) !important; letter-spacing: -0.02em; margin-top: 2.2em; margin-bottom: 0.7em !important; line-height: 1.25; }
.ov-legal section:first-child h2, .ov-legal h2:first-child { margin-top: 0; }
.ov-legal h3 { font-family: var(--font-display); font-size: 1.15rem !important; font-weight: 700; color: var(--color-ink-900); margin-top: 1.6em !important; }
.ov-legal section { margin-bottom: 0 !important; }
.ov-legal a { color: var(--color-ov-700); text-decoration: underline; text-decoration-color: var(--color-ov-300); overflow-wrap: anywhere; }
.ov-legal ul { list-style: disc; padding-left: 1.25em; }
.ov-legal ol { list-style: decimal; padding-left: 1.25em; }
.ov-legal strong { color: var(--color-ink-900); }
.ov-legal p + p { margin-top: 0.75em; }

