import { cn } from "./cn";

/**
 * Einblenden beim Scrollen – ohne eigenen Client-Baustein.
 * Die Klasse `ov-reveal` wird global vom <RevealObserver/> beobachtet
 * (siehe LayoutWrapper). Ohne JavaScript bleibt der Inhalt sichtbar.
 *
 * dir: up (Standard) | left | right | scale
 */
export default function Reveal({ as: Tag = "div", delay = 0, dir, className, style, children, ...rest }) {
  return (
    <Tag
      // RevealObserver ergänzt `is-visible` am Client – auch in Bereichen, die
      // beim Streaming noch nicht hydriert sind. Diese Abweichung ist gewollt.
      suppressHydrationWarning
      className={cn("ov-reveal", className)}
      data-dir={dir}
      style={delay ? { "--ov-delay": `${delay}ms`, ...style } : style}
      {...rest}
    >
      {children}
    </Tag>
  );
}
=== RevealObserver.js
"use client";

import { useEffect } from "react";
import { usePathname } from "next/navigation";

/**
 * Ein einziger IntersectionObserver für alle `.ov-reveal`-Elemente der Seite.
 * Neue Elemente (Routenwechsel, nachgeladene Inhalte) erfasst ein
 * MutationObserver. Sicherheitsnetz: nach 4 s wird alles sichtbar.
 */
export default function RevealObserver() {
  const pfad = usePathname();

  useEffect(() => {
    const root = document.documentElement;
    root.classList.add("js-ready");

    const io = new IntersectionObserver(
      (eintraege) => {
        for (const e of eintraege) {
          if (e.isIntersecting) {
            e.target.classList.add("is-visible");
            io.unobserve(e.target);
          }
        }
      },
      { rootMargin: "0px 0px -8% 0px", threshold: 0.08 }
    );

    const erfassen = (knoten = document) => {
      knoten.querySelectorAll?.(".ov-reveal:not(.is-visible)").forEach((el) => io.observe(el));
    };
    erfassen();

    const mo = new MutationObserver((mutationen) => {
      for (const m of mutationen) {
        m.addedNodes.forEach((n) => {
          if (n.nodeType !== 1) return;
          if (n.classList?.contains("ov-reveal")) io.observe(n);
          erfassen(n);
        });
      }
    });
    mo.observe(document.body, { childList: true, subtree: true });

    const netz = setTimeout(() => {
      document.querySelectorAll(".ov-reveal:not(.is-visible)").forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.top < window.innerHeight) el.classList.add("is-visible");
      });
    }, 4000);

    return () => {
      io.disconnect();
      mo.disconnect();
      clearTimeout(netz);
    };
  }, [pfad]);

  return null;
}
=== CountUp.js
"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Zählt eine Zahl hoch, sobald sie sichtbar wird.
 * Server-HTML enthält bereits den Endwert (SEO, kein Layout-Sprung).
 */
export default function CountUp({ value, decimals = 0, duration = 1600, prefix = "", suffix = "", className }) {
  const ref = useRef(null);
  const ziel = Number(value) || 0;
  const [anzeige, setAnzeige] = useState(ziel);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    let raf;
    const io = new IntersectionObserver(
      ([e]) => {
        if (!e.isIntersecting) return;
        io.disconnect();
        const start = performance.now();
        const schritt = (t) => {
          const p = Math.min((t - start) / duration, 1);
          const eased = 1 - Math.pow(1 - p, 4);
          setAnzeige(ziel * eased);
          if (p < 1) raf = requestAnimationFrame(schritt);
        };
        setAnzeige(0);
        raf = requestAnimationFrame(schritt);
      },
      { threshold: 0.4 }
    );
    io.observe(el);
    return () => {
      io.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [ziel, duration]);

  return (
    <span ref={ref} className={className ? `ov-num ${className}` : "ov-num"}>
      {prefix}
      {anzeige.toLocaleString("de-DE", { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}
      {suffix}
    </span>
  );
}
