    return (
      <>
        <div className="md:hidden"><StepperInnen art={art} status={status} kompakt /></div>
        <div className="hidden md:block"><StepperInnen art={art} status={status} /></div>
      </>
    );
  }
  return <StepperInnen art={art} status={status} kompakt />;
