/* ==================================================================
   DESIGN-SYSTEM 2.0 – Motion, Flächen, Zahlen-Typo, Primitives
   Regelwerk: docs/DESIGN.md. Alles hier animiert nur transform und
   opacity (Ausnahme: stroke-dashoffset bei Linien-Einlauf, einmalig).
   Unter prefers-reduced-motion greift der globale Block oben
   (Dauer 0.01 ms) – Endzustände sind immer per fill-mode gesichert.
   ================================================================== */

:root {
  /* Dauern */
  --ov-dauer-xs: 120ms;  /* Farbe, Fokus, Tooltip */
  --ov-dauer-s: 180ms;   /* Hover, Press, kleine Zustände */
  --ov-dauer-m: 240ms;   /* Dialog, Toast, Tabs, Panels */
  --ov-dauer-l: 420ms;   /* Seiten-/Abschnittswechsel, Stagger-Element */
