/* ==================================================================
   DESIGN-SYSTEM 2.0 – Motion, Flächen, Zahlen-Typo, Primitives
   Regelwerk: docs/DESIGN.md. Alles hier animiert nur transform und
   opacity (Ausnahme: stroke-dashoffset beim Linien-Einlauf, einmalig).
   Unter prefers-reduced-motion greift der globale Block oben
   (Dauer 0.01 ms) – Endzustände sind per fill-mode gesichert.
   ================================================================== */

:root {
  /* Dauern */
  --ov-dauer-xs: 120ms;    /* Farbe, Fokus */
  --ov-dauer-s: 180ms;     /* Hover, Press, Tooltip */
  --ov-dauer-m: 240ms;     /* Dialog, Toast, Tabs, Panels */
  --ov-dauer-l: 420ms;     /* Abschnittswechsel, Stagger-Element */
  --ov-dauer-xl: 700ms;    /* Reveal beim Scrollen, Diagramm-Einlauf */
  --ov-dauer-zahl: 1400ms; /* Zahlen hochzählen */
  --ov-stagger: 60ms;      /* Versatz je Element */

  --ov-ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ov-ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --ov-ease-feder: cubic-bezier(0.34, 1.56, 0.64, 1);

  /* Elevation als Variablen (für Inline-Styles) – identisch zu shadow-e1 … e5 */
  --ov-e1: 0 1px 2px rgba(3, 18, 43, 0.04), 0 1px 1px rgba(3, 18, 43, 0.02);
  --ov-e2: 0 1px 2px rgba(3, 18, 43, 0.04), 0 4px 12px -4px rgba(3, 18, 43, 0.08);
  --ov-e3: 0 2px 4px -1px rgba(3, 18, 43, 0.05), 0 12px 28px -10px rgba(3, 18, 43, 0.16);
  --ov-e4: 0 4px 8px -2px rgba(3, 18, 43, 0.06), 0 24px 48px -16px rgba(3, 18, 43, 0.22);
  --ov-e5: 0 8px 16px -4px rgba(3, 18, 43, 0.08), 0 40px 80px -24px rgba(3, 18, 43, 0.32);

  /* Dunkle Flächen (Navy-Familie, von tief nach erhaben) */
  --ov-nacht-0: #020b1c;  /* Leitstand, Footer-Grund */
  --ov-nacht-1: #03122b;  /* = navy-950, Standard-Dunkelfläche */
  --ov-nacht-2: #071c3d;  /* Karte auf Dunkel */
  --ov-nacht-3: #0c2650;  /* Hover/aktiv auf Dunkel */
  --ov-nacht-linie: rgba(255, 255, 255, 0.1);

