}
.ov-text { font-size: clamp(0.95rem, 0.92rem + 0.12vw, 1.0625rem); line-height: 1.65; }
.ov-klein { font-size: 0.875rem; line-height: 1.55; }
.ov-mikro { font-size: 0.78rem; line-height: 1.45; letter-spacing: 0.005em; }
